<?php use App\Core\{Auth,Csrf};?><div class="row"><div class="col-xl-8"><section class="panel"><div class="d-flex justify-content-between"><h2><?= e($order['code']) ?></h2><span class="status <?= e($order['status']) ?>"><?= e(status_label($order['status'])) ?></span></div><p class="muted"><?= e($order['created_at']) ?> · <?= e($order['payment_method']) ?></p><div class="table-wrap"><table class="table"><thead><tr><th>Sản phẩm</th><th>Giá</th><th>SL</th><th>Tổng</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?= e($i['product_name']) ?><small class="d-block muted"><?= e($i['sku']) ?></small></td><td><?= money($i['unit_price']) ?></td><td><?= $i['quantity'] ?></td><td><?= money((int)$i['unit_price']*$i['quantity']) ?></td></tr><?php endforeach?></tbody></table></div><h2 class="text-end"><?= money($order['total']) ?></h2></section><section class="panel"><h2>Lịch sử trạng thái</h2><?php foreach($history as $h):?><div class="border-bottom py-3"><b><?= e(status_label($h['to_status'])) ?></b><small class="d-block muted mt-1"><?= e($h['created_at']) ?> · <?= e($h['actor']??'Khách hàng') ?></small><p class="small mb-0 mt-1"><?= e($h['note']) ?></p></div><?php endforeach?></section><?php if(Auth::can('payments.manage')):?><section class="panel"><h2>Lịch sử thanh toán</h2><div class="table-wrap"><table class="table"><thead><tr><th>Số tiền</th><th>Trạng thái</th><th>Mã giao dịch</th><th>Ngày</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?= money($p['amount']) ?></td><td><?= e(status_label($p['status'])) ?></td><td><?= e($p['transaction_code']) ?></td><td><?= e($p['paid_at']??$p['created_at']) ?></td></tr><?php endforeach?></tbody></table></div></section><?php endif?><section class="panel"><h2>Ghi chú hỗ trợ</h2><?php foreach($notes as $n):?><p class="border-bottom py-3"><?= e($n['note']) ?><small class="d-block muted mt-2"><?= e($n['actor']) ?> · <?= e($n['created_at']) ?></small></p><?php endforeach?><?php if(Auth::can('support.manage')):?><form action="/admin/orders/<?= $order['id'] ?>/notes" method="post"><?= Csrf::field() ?><textarea class="form-control" name="note" rows="3" maxlength="2000" aria-label="Ghi chú hỗ trợ" required></textarea><button type="submit" class="btn btn-primary mt-3">Lưu ghi chú</button></form><?php endif?></section></div><div class="col-xl-4"><section class="panel"><h2>Thông tin người nhận</h2><p class="lh-lg mt-3"><?= e($order['recipient']) ?><br><?= e($order['phone']) ?><br><?= e($order['address_line']) ?></p><p class="muted"><?= e($order['note']) ?></p></section><section class="panel"><h2>Cập nhật trạng thái</h2><?php $options=[];foreach(App\Services\OrderStatusService::TRANSITIONS[$order['status']] as $s){$p=['processing'=>'orders.confirm','shipping'=>'orders.ship','completed'=>'orders.complete','cancelled'=>'orders.cancel'][$s];if(Auth::can($p)||($s==='processing'&&Auth::can('orders.prepare'))){$options[]=$s;}}?><?php if($options):?><form action="/admin/orders/<?= $order['id'] ?>/status" method="post"><?= Csrf::field() ?><select class="form-select my-3" name="status" aria-label="Trạng thái tiếp theo"><?php foreach($options as $s):?><option value="<?= $s ?>"><?= e(status_label($s)) ?></option><?php endforeach?></select><input class="form-control" name="note" maxlength="500" placeholder="Lý do / ghi chú" aria-label="Lý do"><button class="btn btn-primary mt-3" type="submit">Xác nhận chuyển trạng thái</button></form><?php else:?><p class="muted mt-3">Không có thao tác trạng thái được phép.</p><?php endif?></section><?php if(Auth::can('payments.manage')):?><section class="panel"><h2>Ghi nhận thanh toán</h2><form method="post" action="/admin/orders/<?= $order['id'] ?>/payments"><?= Csrf::field() ?><input type="hidden" name="request_token" value="<?= bin2hex(random_bytes(32)) ?>"><label class="form-label" for="pay-amount">Số tiền (VND)</label><input class="form-control" id="pay-amount" name="amount" type="number" min="1" step="1" required><label class="form-label" for="pay-status">Trạng thái</label><select class="form-select" id="pay-status" name="status"><option value="paid">Đã thanh toán</option><option value="unpaid">Chưa thanh toán (ghi chú)</option><option value="refunded">Hoàn tiền</option></select><label class="form-label" for="pay-method">Phương thức</label><select class="form-select" id="pay-method" name="method"><option value="cod">COD</option><option value="bank_transfer">Chuyển khoản</option></select><label class="form-label" for="pay-code">Mã giao dịch (nếu có)</label><input class="form-control" id="pay-code" name="transaction_code" maxlength="120"><label class="form-label" for="pay-date">Ngày thanh toán</label><input class="form-control" id="pay-date" name="paid_at" type="datetime-local" value="<?= date('Y-m-d\TH:i') ?>"><button class="btn btn-primary mt-3" type="submit">Ghi nhận</button></form></section><?php endif?><?php if(Auth::can('invoices.manage')):?><section class="panel"><h2>Hóa đơn</h2><?php if($invoice):?><a class="btn btn-outline-primary mt-3" href="/admin/invoices/<?= $invoice['id'] ?>">Xem & in hóa đơn</a><?php else:?><form action="/admin/orders/<?= $order['id'] ?>/invoice" method="post"><?= Csrf::field() ?><button class="btn btn-primary mt-3" type="submit">Sinh hóa đơn</button></form><?php endif?></section><?php endif?></div></div>
